<?php
if(!defined('ABSPATH')){exit;}
final class Orion_AI_Evaluation_Service{
 public function run(array $settings,string $suite_file):array{$cases=json_decode((string)file_get_contents($suite_file),true);if(!is_array($cases))return array('rows'=>array(),'summary'=>array('error'=>'Invalid evaluation suite.'));$rows=array();$passed=0;$total_ms=0;$tokens=0;foreach($cases as$case){$state=array();$history=array();$last=array();$started=microtime(true);foreach(($case['messages']??array())as$message){$last=(new Orion_Intent_Classifier())->classify((string)$message,$history,$state,$settings);$state=(new Orion_Context_Manager())->apply($state,$last);$history[]=array('role'=>'user','content'=>(string)$message);$history[]=array('role'=>'assistant','content'=>!empty($last['clarifying_questions'])?implode(' ',(array)$last['clarifying_questions']):'Route recorded.');$tokens+=(int)($last['_diagnostic']['usage']['total_tokens']??0);}$duration=(int)round((microtime(true)-$started)*1000);$total_ms+=$duration;$checks=array();if(isset($case['expected_intent']))$checks[]=(string)($last['intent']??'')===(string)$case['expected_intent'];foreach(($case['expected_state']??array())as$key=>$value)$checks[]=isset($state[$key])&&(string)$state[$key]===(string)$value;$actual_roles=array_column((array)($last['search_plan']??array()),'role');foreach(($case['expected_roles']??array())as$role)$checks[]=in_array($role,$actual_roles,true);foreach(($case['expected_optional_roles']??array())as$role){$optional=false;foreach((array)($last['search_plan']??array())as$item)if(($item['role']??'')===$role&&empty($item['required']))$optional=true;$checks[]=$optional;}foreach(($case['unexpected_roles']??array())as$role)$checks[]=!in_array($role,$actual_roles,true);$diagnostic=(string)($last['_diagnostic']['status']??'');$valid=!in_array($diagnostic,array('provider_error','invalid_output'),true);$checks[]=$valid;$ok=!in_array(false,$checks,true);if($ok)$passed++;$rows[]=array('case'=>sanitize_text_field((string)($case['name']??'Unnamed')),'result'=>$ok?'PASS':'FAIL','intent'=>(string)($last['intent']??''),'diagnostic'=>$diagnostic,'duration_ms'=>$duration,'details'=>$ok?'':wp_json_encode(array('expected_intent'=>$case['expected_intent']??null,'state'=>$state),JSON_UNESCAPED_UNICODE));}return array('rows'=>$rows,'summary'=>array('passed'=>$passed,'total'=>count($rows),'pass_rate'=>$rows?round($passed/count($rows)*100,1):0,'duration_ms'=>$total_ms,'average_ms'=>$rows?(int)round($total_ms/count($rows)):0,'total_tokens'=>$tokens));}
}
